/* Game details: cover plus year/genre/developer/description, generated by tools/gen_covers.py. */
#pragma once
#include <stdint.h>

#define COVER_W 60 /* tools/gen_covers.py writes this size */
#define COVER_H 86

typedef struct {
    int system_index, sel, has_cover;
    uint32_t cover[COVER_W * COVER_H];
    char year[8], genre[48], dev[64], desc[700];
} game_details_t;

/* Finds in the cache, or loads into a free slot, without changing the current details. */
const game_details_t *details_find(int system_index, int sel);
void details_select(int system_index, int sel); /* makes that game the current one */
const game_details_t *details_current(void);
void details_invalidate(void);

void details_rom_basename(const char *file, char *out, int max); /* file name without its extension */
